        ["PASO 3 · CONEXIÓN"] = ["STEP 3 · CONNECTION", "SCHRITT 3 · VERBINDUNG", "PASO 3 · CONEXIÓN", "ÉTAPE 3 · CONNEXION", "PASSAGGIO 3 · CONNESSIONE", "ETAPA 3 · CONEXÃO", "ШАГ 3 · ПОДКЛЮЧЕНИЕ"],
        ["Conexión con el televisor"] = ["TV connection", "Verbindung mit dem Fernseher", "Conexión con el televisor", "Connexion au téléviseur", "Connessione alla TV", "Conexão com a TV", "Подключение к телевизору"],
        ["The following device has been detected. Click the “Next” button when you are ready to continue."] = ["The following device has been detected. Click the “Next” button when you are ready to continue.", "Das folgende Gerät wurde erkannt. Klicke auf „Weiter“, wenn du bereit bist, fortzufahren.", "Se ha detectado el siguiente dispositivo. Pulsa el botón «Siguiente» cuando estés listo para continuar.", "L’appareil suivant a été détecté. Cliquez sur le bouton « Suivant » lorsque vous êtes prêt à continuer.", "È stato rilevato il seguente dispositivo. Fai clic su «Avanti» quando sei pronto per continuare.", "O seguinte dispositivo foi detectado. Clique em “Avançar” quando estiver pronto para continuar.", "Обнаружено следующее устройство. Когда будете готовы продолжить, нажмите кнопку «Далее»."],
        ["The following devices have been detected. Select the one you want to use, then click the “Next” button when you are ready to continue."] = ["The following devices have been detected. Select the one you want to use, then click the “Next” button when you are ready to continue.", "Die folgenden Geräte wurden erkannt. Wähle das gewünschte Gerät aus und klicke auf „Weiter“, wenn du bereit bist, fortzufahren.", "Se han detectado los siguientes dispositivos. Selecciona el que quieras utilizar y pulsa el botón «Siguiente» cuando estés listo para continuar.", "Les appareils suivants ont été détectés. Sélectionnez celui que vous souhaitez utiliser, puis cliquez sur le bouton « Suivant » lorsque vous êtes prêt à continuer.", "Sono stati rilevati i seguenti dispositivi. Seleziona quello che desideri utilizzare e fai clic su «Avanti» quando sei pronto per continuare.", "Os seguintes dispositivos foram detectados. Selecione aquele que deseja usar e clique em “Avançar” quando estiver pronto para continuar.", "Обнаружены следующие устройства. Выберите нужное и нажмите кнопку «Далее», когда будете готовы продолжить."],
        ["PASO 4 · RESULTADO"] = ["STEP 4 · RESULT", "SCHRITT 4 · ERGEBNIS", "PASO 4 · RESULTADO", "ÉTAPE 4 · RÉSULTAT", "PASSAGGIO 4 · RISULTATO", "ETAPA 4 · RESULTADO", "ШАГ 4 · РЕЗУЛЬТАТ"],
        ["Resultado de la transferencia"] = ["Transfer result", "Übertragungsergebnis", "Resultado de la transferencia", "Résultat du transfert", "Risultato del trasferimento", "Resultado da transferência", "Результат передачи"],
        ["Transferencia completada"] = ["Transfer complete", "Übertragung abgeschlossen", "Transferencia completada", "Transfert terminé", "Trasferimento completato", "Transferência concluída", "Передача завершена"],
        ["No se ha podido transferir el paquete"] = ["The package could not be transferred", "Das Paket konnte nicht übertragen werden", "No se ha podido transferir el paquete", "Le paquet n’a pas pu être transféré", "Impossibile trasferire il pacchetto", "Não foi possível transferir o pacote", "Не удалось передать пакет"],
        ["Moonlight para Tizen se ha transferido correctamente a TV-Store. Para completar la instalación, acepta el mensaje de confirmación que aparecerá en la televisión. Si no aparece, abre TV-Store en el televisor y confirma allí la instalación."] = ["Moonlight for Tizen was successfully transferred to TV-Store. To complete installation, accept the confirmation prompt on your TV. If it does not appear, open TV-Store on the television and confirm the installation there.", "Moonlight für Tizen wurde erfolgreich an TV-Store übertragen. Bestätige zur Installation die Meldung auf deinem Fernseher. Falls sie nicht erscheint, öffne TV-Store auf dem Fernseher und bestätige die Installation dort.", "Moonlight para Tizen se ha transferido correctamente a TV-Store. Para completar la instalación, acepta el mensaje de confirmación que aparecerá en la televisión. Si no aparece, abre TV-Store en el televisor y confirma allí la instalación.", "Moonlight pour Tizen a été transféré avec succès vers TV-Store. Pour terminer l’installation, acceptez le message de confirmation sur votre téléviseur. S’il n’apparaît pas, ouvrez TV-Store sur le téléviseur et confirmez l’installation.", "Moonlight per Tizen è stato trasferito correttamente a TV-Store. Per completare l’installazione, accetta il messaggio di conferma sulla TV. Se non appare, apri TV-Store sul televisore e conferma l’installazione.", "Moonlight para Tizen foi transferido com sucesso para o TV-Store. Para concluir a instalação, aceite a mensagem de confirmação na TV. Se ela não aparecer, abra o TV-Store na televisão e confirme a instalação.", "Moonlight для Tizen успешно передан в TV-Store. Чтобы завершить установку, подтвердите запрос на телевизоре. Если запрос не появится, откройте TV-Store на телевизоре и подтвердите установку."],
        ["No se ha podido entregar Moonlight.wgt a TV-Store y la aplicación no se ha instalado. Comprueba que el televisor sigue conectado y vuelve a ejecutar el instalador. Si prefieres utilizar la instalación normal, rechaza la opción de TV-Store cuando vuelva a aparecer."] = new string[] {"Moonlight.wgt could not be delivered to TV-Store, so the application was not installed. Check that the TV is still connected and run the installer again. To use the normal installation route, decline TV-Store when prompted again.", "Moonlight.wgt konnte nicht an TV-Store übergeben werden; die Anwendung wurde nicht installiert. Prüfe die Verbindung des Fernsehers und starte das Installationsprogramm erneut. Um die normale Installation zu verwenden, lehne TV-Store bei der nächsten Abfrage ab.", "No se ha podido entregar Moonlight.wgt a TV-Store y la aplicación no se ha instalado. Comprueba que el televisor sigue conectado y vuelve a ejecutar el instalador. Si prefieres utilizar la instalación normal, rechaza la opción de TV-Store cuando vuelva a aparecer.", "Moonlight.wgt n’a pas pu être envoyé à TV-Store et l’application n’a pas été installée. Vérifiez la connexion du téléviseur et relancez le programme. Pour utiliser l’installation normale, refusez TV-Store lors de la prochaine demande.", "Moonlight.wgt non è stato inviato a TV-Store e l’applicazione non è stata installata. Verifica la connessione della TV e riavvia il programma. Per usare l’installazione normale, rifiuta TV-Store alla prossima richiesta.", "Não foi possível enviar Moonlight.wgt para o TV-Store e o aplicativo não foi instalado. Verifique a conexão da TV e execute o instalador novamente. Para usar a instalação normal, recuse o TV-Store quando solicitado.", "Moonlight.wgt не удалось передать в TV-Store, поэтому приложение не установлено. Проверьте подключение телевизора и запустите установщик снова. Чтобы использовать обычный способ установки, отклоните предложение TV-Store при следующем запросе."},
        ["Completa la instalación en el televisor"] = ["Complete the installation on your TV", "Schließe die Installation auf dem Fernseher ab", "Completa la instalación en el televisor", "Terminez l’installation sur le téléviseur", "Completa l’installazione sulla TV", "Conclua a instalação na TV", "Завершите установку на телевизоре"],
        ["Finalizar"] = ["Finish", "Fertigstellen", "Finalizar", "Terminer", "Fine", "Concluir", "Готово"],
        ["PASO 4 · CERTIFICADO"] = ["STEP 4 · CERTIFICATE", "SCHRITT 4 · ZERTIFIKAT", "PASO 4 · CERTIFICADO", "ÉTAPE 4 · CERTIFICAT", "PASSAGGIO 4 · CERTIFICATO", "ETAPA 4 · CERTIFICADO", "ШАГ 4 · СЕРТИФИКАТ"],
        ["Preparar el certificado de instalación"] = ["Prepare the installation certificate", "Installationszertifikat vorbereiten", "Preparar el certificado de instalación", "Préparer le certificat d’installation", "Preparare il certificato di installazione", "Preparar o certificado de instalação", "Подготовка сертификата установки"],
        ["Abrir sitio web para iniciar sesión ↗"] = ["Open website to sign in ↗", "Website öffnen und anmelden ↗", "Abrir sitio web para iniciar sesión ↗", "Ouvrir le site web pour se connecter ↗", "Apri il sito web per accedere ↗", "Abrir o site para iniciar sessão ↗", "Открыть сайт для входа ↗"],
        ["Because this is the first time you are installing Moonlight from this computer, you need to prepare a certificate. Sign in to the Samsung website with your account, or create one if you do not have one yet. The certificate will be stored in the current user account on this computer and reused automatically for future installations."] = ["Because this is the first time you are installing Moonlight from this computer, you need to prepare a certificate. Sign in to the Samsung website with your account, or create one if you do not have one yet. The certificate will be stored in the current user account on this computer and reused automatically for future installations.", "Da du Moonlight zum ersten Mal auf diesem Computer installierst, musst du ein Zertifikat vorbereiten. Melde dich mit deinem Konto auf der Samsung-Website an oder erstelle eines, falls du noch keines hast. Das Zertifikat wird im aktuellen Benutzerkonto dieses Computers gespeichert und bei künftigen Installationen automatisch wiederverwendet.", "Como es la primera vez que instalas Moonlight desde este ordenador, necesitas preparar un certificado. Inicia sesión en el sitio web de Samsung con tu cuenta o créala si aún no tienes. El certificado quedará guardado en la cuenta del usuario actual de este equipo y se reutilizará automáticamente en próximas instalaciones.", "Puisque vous installez Moonlight pour la première fois depuis cet ordinateur, vous devez préparer un certificat. Connectez-vous au site web de Samsung avec votre compte ou créez-en un si vous n’en avez pas encore. Le certificat sera conservé dans le compte de l’utilisateur actuel de cet ordinateur et réutilisé automatiquement lors des prochaines installations.", "Poiché è la prima volta che installi Moonlight da questo computer, devi preparare un certificato. Accedi al sito Samsung con il tuo account oppure creane uno se non ne hai ancora. Il certificato verrà salvato nell’account utente corrente di questo computer e riutilizzato automaticamente per le installazioni successive.", "Como esta é a primeira instalação do Moonlight neste computador, é necessário preparar um certificado. Entre no site da Samsung com sua conta ou crie uma, caso ainda não tenha. O certificado ficará armazenado na conta do usuário atual deste computador e será reutilizado automaticamente nas próximas instalações.", "Поскольку вы впервые устанавливаете Moonlight с этого компьютера, необходимо подготовить сертификат. Войдите на сайт Samsung под своей учётной записью или создайте её, если у вас её ещё нет. Сертификат будет сохранён в учётной записи текущего пользователя этого компьютера и автоматически использован при следующих установках."],
        ["Certificado de instalación"] = ["Installation certificate", "Installationszertifikat", "Certificado de instalación", "Certificat d’installation", "Certificato di installazione", "Certificado de instalação", "Сертификат установки"],
        ["El certificado para la instalación de Moonlight en su televisión ya está preparado. Cuando esté listo para instalar la aplicación pulse en el botón Instalar para iniciar la transferencia y terminar."] = ["The certificate for installing Moonlight on your TV is ready. When you are ready, click Install to start the transfer and finish.", "Das Zertifikat für die Installation von Moonlight auf deinem Fernseher ist bereit. Klicke auf Installieren, um die Übertragung zu starten und den Vorgang abzuschließen.", "El certificado para la instalación de Moonlight en su televisión ya está preparado. Cuando esté listo para instalar la aplicación pulse en el botón Instalar para iniciar la transferencia y terminar.", "Le certificat nécessaire à l’installation de Moonlight sur votre téléviseur est prêt. Cliquez sur Installer pour lancer le transfert et terminer.", "Il certificato per installare Moonlight sulla TV è pronto. Quando sei pronto, fai clic su Installa per avviare il trasferimento e terminare.", "O certificado para instalar o Moonlight na sua TV está pronto. Quando estiver pronto, clique em Instalar para iniciar a transferência e concluir.", "Сертификат для установки Moonlight на телевизор готов. Нажмите «Установить», чтобы начать передачу и завершить процесс."],
        ["Emitido: {0} · Caduca: {1}"] = ["Issued: {0} · Expires: {1}", "Ausgestellt: {0} · Läuft ab: {1}", "Emitido: {0} · Caduca: {1}", "Délivré : {0} · Expire le : {1}", "Emesso: {0} · Scade: {1}", "Emitido: {0} · Expira: {1}", "Выдан: {0} · Истекает: {1}"],
