        ["Se está preparando y transfiriendo Moonlight al televisor. Este proceso puede tardar unos instantes."] = ["Moonlight is being prepared and transferred to your TV. This may take a few moments.", "Moonlight wird vorbereitet und auf deinen Fernseher übertragen. Dies kann einen Moment dauern.", "Se está preparando y transfiriendo Moonlight al televisor. Este proceso puede tardar unos instantes.", "Moonlight est en cours de préparation et de transfert vers votre téléviseur. Cela peut prendre quelques instants.", "Moonlight è in preparazione e trasferimento sulla TV. L’operazione potrebbe richiedere alcuni istanti.", "O Moonlight está sendo preparado e transferido para sua TV. Isso pode levar alguns instantes.", "Moonlight подготавливается и передаётся на телевизор. Это может занять несколько секунд."],
        ["Preparando la instalación…"] = ["Preparing installation…", "Installation wird vorbereitet…", "Preparando la instalación…", "Préparation de l’installation…", "Preparazione dell’installazione…", "Preparando a instalação…", "Подготовка установки…"],
        ["Instalación completada"] = ["Installation complete", "Installation abgeschlossen", "Instalación completada", "Installation terminée", "Installazione completata", "Instalação concluída", "Установка завершена"],
        ["If you want to uninstall the current version and try again, click “Uninstall & retry”."] = ["If you want to uninstall the current version and try again, click “Uninstall & retry”.", "Wenn du die aktuelle Version deinstallieren und es erneut versuchen möchtest, klicke auf „Deinstallieren und erneut versuchen“.", "Si quieres desinstalar la versión actual y volver a intentarlo, pulsa «Desinstalar y reintentar».", "Si vous souhaitez désinstaller la version actuelle et réessayer, cliquez sur « Désinstaller et réessayer ».", "Se vuoi disinstallare la versione attuale e riprovare, fai clic su «Disinstalla e riprova».", "Se quiser desinstalar a versão atual e tentar novamente, clique em “Desinstalar e tentar novamente”.", "Если вы хотите удалить текущую версию и повторить попытку, нажмите «Удалить и повторить попытку»."] ,
        ["Uninstall & retry"] = ["Uninstall & retry", "Deinstallieren und erneut versuchen", "Desinstalar y reintentar", "Désinstaller et réessayer", "Disinstalla e riprova", "Desinstalar e tentar novamente", "Удалить и повторить попытку"],
        ["Uninstalling Moonlight…"] = ["Uninstalling Moonlight…", "Moonlight wird deinstalliert…", "Desinstalando Moonlight…", "Désinstallation de Moonlight…", "Disinstallazione di Moonlight…", "Desinstalando o Moonlight…", "Удаление Moonlight…"],
